const menuButton=document.querySelector('.menu-button');const nav=document.querySelector('.nav');menuButton?.addEventListener('click',()=>{const open=nav.classList.toggle('open');menuButton.setAttribute('aria-expanded',open)});document.querySelectorAll('.nav a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menuButton?.setAttribute('aria-expanded','false')}));const form=document.querySelector('#contact-form');form?.addEventListener('submit',e=>{e.preventDefault();form.querySelector('.form-status').textContent='Mensagem registrada. Configure o destino do formulário antes da publicação final.';form.reset()});const ctas=[['programa','Conhecer o programa'],['protocolos','Falar com especialista'],['execucao','Agendar uma conversa'],['equipe','Falar com a equipe']];ctas.forEach(([id,label])=>{const section=document.getElementById(id);if(section){const wrap=document.createElement('p');wrap.className='section-action';wrap.innerHTML=`<a class="button button-gold" href="#contato">${label}</a>`;section.append(wrap)}});const animated=[...document.querySelectorAll('.section,.value,.contact,.reveal')];const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}}),{threshold:.14});animated.forEach((item,index)=>{item.style.transitionDelay=`${Math.min(index%4,2)*80}ms`;observer.observe(item)});
